import {BatController} from '../input.js';
import {BallSimulation,v} from '../physics.js';
// Identical observed full deliveries. No special contact or outcome adjustment.
export function driveComparison(){const attempts=[];for(const angle of [90,65,45,20]){const control=new BatController();control.gestureEnabled=true;control.poseController.physicalEnabled=true;control.poseController.shot='straight';const sim=new BallSimulation({position:v(0,2,-18),velocity:v(0,-1.5,32),spin:v(),seamNormal:v(1,0,0),seamCoefficient:0}),frames=[];let ended=false;for(let tick=0;tick<1800;tick++){const t=tick*.001;control.poseController.observe(sim.dead?null:sim.position,sim.dead?null:sim.velocity);if(tick===70)control.gestures.begin(.5,.65,t,'test');if(tick>70&&tick<=430&&tick%10===0){const phase=(tick-70)/360,a=angle*Math.PI/180;control.gestures.sample(.5+Math.cos(a)*phase*.35,.65-Math.sin(a)*phase*.35,t);}if(tick===430){control.gestures.end(t);ended=true;}const pose=control.step(.001);if(!sim.dead){sim.step(pose);if(sim.contact&&sim.contact.timeS===sim.time)control.poseController.impact(sim.contact);}if(tick%10===0)frames.push({time:t,pose:structuredClone(pose),ball:{...sim.position}});}attempts.push({angle,features:control.gestures.gesture.features,events:sim.events,frames});}return {description:'Four directions against identical full releases; actual collision may miss.',attempts};}
